lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --threads 14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --threads-batch 8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --host $&amp;#123;host&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;&lt;/span&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;ttl:&lt;/span&gt; &lt;span class=&#34;hljs-number&#34;&gt;120&lt;/span&gt;&lt;br&gt;&lt;br&gt;  &lt;span class=&#34;hljs-comment&#34;&gt;# ===== 纯 CPU 常驻（物理隔离，不占显存）=====&lt;/span&gt;&lt;br&gt;  &lt;span class=&#34;hljs-attr&#34;&gt;&amp;quot;qwen3-embedding:0.6b-cpu&amp;quot;:&lt;/span&gt;&lt;br&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;cmd:&lt;/span&gt; &lt;span class=&#34;hljs-string&#34;&gt;|&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      env CUDA_VISIBLE_DEVICES=&amp;quot;&amp;quot; llama-server&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --host $&amp;#123;host&amp;#125; --port $&amp;#123;PORT&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --model /ssd-models/Qwen/Qwen3-Embedding-0.6B-GGUF/Qwen3-Embedding-0.6B-Q8_0.gguf&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --n-gpu-layers $&amp;#123;n_gpu_layers_cpu&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --load-mode none&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --threads 14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --pooling last&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --embeddings&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;&lt;/span&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;ttl:&lt;/span&gt; &lt;span class=&#34;hljs-number&#34;&gt;60&lt;/span&gt;&lt;br&gt;&lt;br&gt;  &lt;span class=&#34;hljs-attr&#34;&gt;&amp;quot;qwen3-reranker:0.6b-cpu&amp;quot;:&lt;/span&gt;&lt;br&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;cmd:&lt;/span&gt; &lt;span class=&#34;hljs-string&#34;&gt;|&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      env CUDA_VISIBLE_DEVICES=&amp;quot;&amp;quot; llama-server&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --host $&amp;#123;host&amp;#125; --port $&amp;#123;PORT&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --model /ssd-models/Voodisss/Qwen3-Reranker-0.6B-GGUF-llama_cpp/Qwen3-Reranker-0.6B-Q6_K.gguf&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --n-gpu-layers $&amp;#123;n_gpu_layers_cpu&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --load-mode none&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --ctx-size $&amp;#123;ctx_size_32k&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --threads 14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --pooling rank&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --embeddings&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --reranking&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;&lt;/span&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;ttl:&lt;/span&gt; &lt;span class=&#34;hljs-number&#34;&gt;60&lt;/span&gt;&lt;br&gt;&lt;br&gt;  &lt;span class=&#34;hljs-attr&#34;&gt;&amp;quot;qwen3.5:0.8b-cpu&amp;quot;:&lt;/span&gt;&lt;br&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;cmd:&lt;/span&gt; &lt;span class=&#34;hljs-string&#34;&gt;|&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      env CUDA_VISIBLE_DEVICES=&amp;quot;&amp;quot; llama-server&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --host $&amp;#123;host&amp;#125; --port $&amp;#123;PORT&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --model /ssd-models/unsloth/Qwen3.5-0.8B-MTP-GGUF/Qwen3.5-0.8B-UD-Q6_K_XL.gguf&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --mmproj /ssd-models/unsloth/Qwen3.5-0.8B-MTP-GGUF/mmproj-BF16.gguf&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --n-gpu-layers $&amp;#123;n_gpu_layers_cpu&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --load-mode none&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --ctx-size $&amp;#123;ctx_size_64k&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --jinja --chat-template-file /ssd-models/froggeric/Qwen-Fixed-Chat-Templates/chat_template.jinja&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --chat-template-kwargs &amp;#x27;&amp;#123;&amp;quot;enable_thinking&amp;quot;: false&amp;#125;&amp;#x27;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --reasoning off&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --threads 14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --threads-batch 8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;&lt;/span&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;ttl:&lt;/span&gt; &lt;span class=&#34;hljs-number&#34;&gt;120&lt;/span&gt;&lt;br&gt;&lt;br&gt;  &lt;span class=&#34;hljs-attr&#34;&gt;&amp;quot;d3-mini:q4-cpu&amp;quot;:&lt;/span&gt;&lt;br&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;cmd:&lt;/span&gt; &lt;span class=&#34;hljs-string&#34;&gt;|&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      env CUDA_VISIBLE_DEVICES=&amp;quot;&amp;quot; llama-server&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --host $&amp;#123;host&amp;#125; --port $&amp;#123;PORT&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --model /ssd-models/ggml-org/vllm-d3-mini-GGUF/vllm-d3-mini-Q4_K_M.gguf&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --n-gpu-layers $&amp;#123;n_gpu_layers_cpu&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --load-mode none&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      -c $&amp;#123;ctx_size_16k&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --threads 14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --threads-batch 14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;      --parallel 1 --ctx-checkpoints 0 -b 16384 -ub 16384&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;hljs-string&#34;&gt;&lt;/span&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;ttl:&lt;/span&gt; &lt;span class=&#34;hljs-number&#34;&gt;300&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;span class=&#34;hljs-attr&#34;&gt;groups:&lt;/span&gt;&lt;br&gt;  &lt;span class=&#34;hljs-attr&#34;&gt;cpu-group:&lt;/span&gt;            &lt;span class=&#34;hljs-comment&#34;&gt;# 常驻不换入换出，检索与决策链路永不误伤&lt;/span&gt;&lt;br&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;swap:&lt;/span&gt; &lt;span class=&#34;hljs-literal&#34;&gt;false&lt;/span&gt;&lt;br&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;persistent:&lt;/span&gt; &lt;span class=&#34;hljs-literal&#34;&gt;true&lt;/span&gt;&lt;br&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;exclusive:&lt;/span&gt; &lt;span class=&#34;hljs-literal&#34;&gt;false&lt;/span&gt;&lt;br&gt;    &lt;span class=&#34;hljs-attr&#34;&gt;members:&lt;/span&gt;&lt;br&gt;      &lt;span class=&#34;hljs-bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;hljs-string&#34;&gt;qwen3-embedding:0.6b-cpu&lt;/span&gt;&lt;br&gt;      &lt;span class=&#34;hljs-bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;hljs-string&#34;&gt;qwen3-reranker:0.6b-cpu&lt;/span&gt;&lt;br&gt;      &lt;span class=&#34;hljs-bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;hljs-string&#34;&gt;qwen3.5:0.8b-cpu&lt;/span&gt;&lt;br&gt;      &lt;span class=&#34;hljs-bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;hljs-string&#34;&gt;d3-mini:q4-cpu&lt;/span&gt;&lt;br&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;一点收尾&#34;&gt;&lt;a href=&#34;#一点收尾&#34; class=&#34;headerlink&#34; title=&#34;一点收尾&#34;&gt;&lt;/a&gt;一点收尾&lt;/h2&gt;&lt;p&gt;回头看，llama-swap 官方 README 说的是 “swap models on-demand”，我实际用它做的是 &lt;strong&gt;swap engines&lt;/strong&gt;：llama.cpp、Strata、vLLM 三个推理引擎加一个协议转换出来的 ComfyUI，四种 backend 打通了 &lt;strong&gt;GGUF、vLLM、ComfyUI 三大模型生态&lt;/strong&gt;，共享同一个 OpenAI 兼容入口、同一套生命周期管理、同一块 16GB 显存。&lt;/p&gt;
&lt;p&gt;这个方案的适用画像很清晰：单机、单卡、负载类型多但每种都不是 7×24、换入成本可以接受（GGUF 量化换入快，vLLM 靠 enforce-eager 压冷启动）。如果你的场景是”一张卡要养聊天、生图、语音、检索一整支杂牌军”，别给每个引擎建一套独立运维面——把它们统统变成 llama-swap 的 upstream，分时复用，一个端口走天下。&lt;/p&gt;
&lt;p&gt;而且这张总线没有封顶的意思：TTS、视频理解、下一个还没出现的新引擎——只要能”监听指定端口”，位置早就给它留好了。&lt;strong&gt;接入成本总结成一句话：写一个启动脚本，加一段 yaml，完事。&lt;/strong&gt;&lt;/p&gt;

 &lt;p&gt;个人建站、应用初创、商业化demo验证，都依赖一些赛博基建设施，盘点记录一下我积攒的免费赛博基建好物。注意我记录的免费方案不是临时白嫖那种，是能长期稳定使用的。&lt;/p&gt;
&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h1 id=&#34;1-域名&#34;&gt;&lt;a href=&#34;#1-域名&#34; class=&#34;headerlink&#34; title=&#34;1 域名&#34;&gt;&lt;/a&gt;1 域名&lt;/h1&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 一个稳定可用的域名是任何网络应用的公网门户与最直观基础的推广门槛。但是绝大部分情况下，自定义域名要收费，这实在是很扫兴，就没有免费自定义域名可以用吗？有的兄弟，有的。&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 有这样一个公益项目&lt;a href=&#34;https://github.com/DigitalPlatDev/FreeDomain&#34;&gt;FreeDomain&lt;/a&gt;，出发点就是让所有人都有机会拥有一个自己的域名，让任何idea能够在公网顺畅落地推广。这个项目是非营利组织&lt;a href=&#34;https://github.com/DigitalPlatDev&#34;&gt;DigitalPlat Foundation&lt;/a&gt;的子项目之一，这个组织旨在降低独立开发者的赛博基建门槛。&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 具体的，有几个公益一级域名 ，通过比较简单的注册流程，就能在这些一级域名下创建自定义的二级域名并自由使用。这些一级域名包括：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;.DPDNS.ORG&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;.US.KG&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;.QZZ.IO&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;.XX.KG&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 实测可用，要是哪天我的主域名懒得续费或者受到什么限制，说不定就切到我的免费备用域名上了。目前暂时只用免费域名配合赛博活菩萨Cloudfare搭建海外免费CDN。&lt;/p&gt;
&lt;h1 id=&#34;2-VPS（不推荐免费，留着只为提示避坑）&#34;&gt;&lt;a href=&#34;#2-VPS（不推荐免费，留着只为提示避坑）&#34; class=&#34;headerlink&#34; title=&#34;2 VPS（不推荐免费，留着只为提示避坑）&#34;&gt;&lt;/a&gt;2 VPS（不推荐免费，留着只为提示避坑）&lt;/h1&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 永久免费VPS实例据我所知只有&lt;a href=&#34;https://www.oracle.com/cn/cloud/free/&#34;&gt;Oracle Cloud&lt;/a&gt;一家提供，&lt;b style=&#34;color: red;&#34;&gt;但是別试，別试！&lt;/b&gt;。注册卡人，出了名的折磨人。注册成功了也还有资源卡人，开出免费实例的很少。&lt;/p&gt;
&lt;h1 id=&#34;3-DNS&#34;&gt;&lt;a href=&#34;#3-DNS&#34; class=&#34;headerlink&#34; title=&#34;3 DNS&#34;&gt;&lt;/a&gt;3 DNS&lt;/h1&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 有了域名，也有了VPS（或者SaaS），还需要一个DNS把两者联系起来，免费DNS不少，国内我用&lt;a href=&#34;https://www.dnspod.cn/&#34;&gt;DNSPod&lt;/a&gt;（已被腾讯云收购，算国内大厂维护了），国外我用赛博活菩萨&lt;a href=&#34;https://www.cloudflare-cn.com/application-services/products/dns/&#34;&gt;Cloudfare&lt;/a&gt;。为什么不统一用Cloudfare？DNSPod能加分区解析策略，例如国内外分流的CDN策略（别急，到CDN了细说）。&lt;/p&gt;
&lt;h1 id=&#34;4-邮件服务器&#34;&gt;&lt;a href=&#34;#4-邮件服务器&#34; class=&#34;headerlink&#34; title=&#34;4 邮件服务器&#34;&gt;&lt;/a&gt;4 邮件服务器&lt;/h1&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 怎么为自己的域名配置邮件服务器？以前QQ邮箱能免费开自定义域名邮箱，现在变会员功能了。当然可以在VPS上自建邮件服务器，但有更方便的白嫖方案——&lt;a href=&#34;https://resend.com/domains&#34;&gt;Resend&lt;/a&gt;。免费档位套餐限制3000邮件&amp;#x2F;月，100邮件&amp;#x2F;日，超过这个量还不盈利，难道在做公益？&lt;/p&gt;
&lt;h1 id=&#34;5-评论插件&#34;&gt;&lt;a href=&#34;#5-评论插件&#34; class=&#34;headerlink&#34; title=&#34;5 评论插件&#34;&gt;&lt;/a&gt;5 评论插件&lt;/h1&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 早些年有个多说插件，黄了，现在有一些收费方案和与特定账号体系高度绑定的半吊子开源方案，我选择在VPS上独立部署&lt;a href=&#34;https://waline.js.org/guide/deploy/&#34;&gt;Waline&lt;/a&gt;，很轻，对VPS负担很小的。&lt;/p&gt;
&lt;h1 id=&#34;6-对象存储&#34;&gt;&lt;a href=&#34;#6-对象存储&#34; class=&#34;headerlink&#34; title=&#34;6 对象存储&#34;&gt;&lt;/a&gt;6 对象存储&lt;/h1&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 图床、数据中转，都是对象存储的典型使用场景，我给两个方案：&lt;/p&gt;
&lt;h2 id=&#34;6-1-自部署&#34;&gt;&lt;a href=&#34;#6-1-自部署&#34; class=&#34;headerlink&#34; title=&#34;6.1 自部署&#34;&gt;&lt;/a&gt;6.1 自部署&lt;/h2&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 如果你有个 NAS，或者一台常驻运行且磁盘空间客观的小服务器，可以选择用s3协议对象存储开源方案——minio自部署对象存储服务，部署方案我在&lt;a href=&#34;https://bipedalbit.net/2025/06/07/%E5%86%8D%E8%B0%88hexo%E9%9D%99%E6%80%81%E7%AB%99%E6%90%AD%E5%BB%BA/#%E5%9B%BE%E5%BA%8A&#34;&gt;静态站搭建的博客文&lt;/a&gt;里有详细介绍。&lt;/p&gt;
&lt;h2 id=&#34;6-2-Cloudfare-R2&#34;&gt;&lt;a href=&#34;#6-2-Cloudfare-R2&#34; class=&#34;headerlink&#34; title=&#34;6.2 Cloudfare-R2&#34;&gt;&lt;/a&gt;6.2 Cloudfare-R2&lt;/h2&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 说起白嫖，赛博活菩萨Cloudfare真是很难绕开。他们家的对象存储&lt;a href=&#34;https://developers.cloudflare.com/r2/pricing/&#34;&gt;R2&lt;/a&gt;，绑个信用卡就能用，免费套餐限制是：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Storage&lt;/th&gt;
&lt;th&gt;10 GB-month &amp;#x2F; month&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;Class A Operations&lt;/td&gt;
&lt;td&gt;1 million requests &amp;#x2F; month&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Class B Operations&lt;/td&gt;
&lt;td&gt;10 million requests &amp;#x2F; month&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 其中A类大致上是管理类或写操作，B类大致是常规读操作。具体定义自己看&lt;a href=&#34;https://developers.cloudflare.com/r2/pricing/&#34;&gt;文档&lt;/a&gt;吧。&lt;/p&gt;
&lt;h1 id=&#34;7-CDN&#34;&gt;&lt;a href=&#34;#7-CDN&#34; class=&#34;headerlink&#34; title=&#34;7 CDN&#34;&gt;&lt;/a&gt;7 CDN&lt;/h1&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 国内老实说我没找到长期免费且稳定的CDN方案，海外流量还得是看&lt;a href=&#34;https://developers.cloudflare.com/cache/&#34;&gt;Cloudflare的CDN&lt;/a&gt;，为什么国内不用他们家？长期维护自建站过程中我发现，由于国内白嫖党太多，赛博活菩萨家的CDN都偶发不稳定了你敢信？&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 那整体CDN策略怎么做？我选择在DNSPod上给静态资源路由做分流，国内流量直连对象存储，海外流量转到我的免费域名，免费域名配到Cloudfare，开启CDN。&lt;/p&gt;
&lt;h1 id=&#34;8-大模型&#34;&gt;&lt;a href=&#34;#8-大模型&#34; class=&#34;headerlink&#34; title=&#34;8 大模型&#34;&gt;&lt;/a&gt;8 大模型&lt;/h1&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 还是给2个方案，可以组合使用：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/ollama/ollama&#34;&gt;ollama&lt;/a&gt;&amp;#x2F;&lt;a href=&#34;https://github.com/Comfy-Org/ComfyUI&#34;&gt;comfyui&lt;/a&gt;本地部署&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://openrouter.ai/&#34;&gt;openrouter&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;用&lt;a href=&#34;https://github.com/songquanpeng/one-api&#34;&gt;one-api&lt;/a&gt;使用openai格式做API汇聚，可以参考我&lt;a href=&#34;https://bipedalbit.net/2025/05/28/%E6%90%AD%E5%BB%BA%E7%A7%81%E6%9C%89LLM%E5%8A%A9%E6%89%8B%E5%B9%B3%E5%8F%B0/&#34;&gt;博文&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;大模型交互方案我选&lt;a href=&#34;https://github.com/open-webui/open-webui&#34;&gt;open-webui&lt;/a&gt;，可以参考我&lt;a href=&#34;https://bipedalbit.net/2025/05/28/%E6%90%AD%E5%BB%BA%E7%A7%81%E6%9C%89LLM%E5%8A%A9%E6%89%8B%E5%B9%B3%E5%8F%B0/&#34;&gt;博文&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;8-1-ollama自部署&#34;&gt;&lt;a href=&#34;#8-1-ollama自部署&#34; class=&#34;headerlink&#34; title=&#34;8.1 ollama自部署&#34;&gt;&lt;/a&gt;8.1 ollama自部署&lt;/h2&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 主要文本类大模型部署用，不用工业级的&lt;a href=&#34;https://github.com/vllm-project/vllm&#34;&gt;vllm&lt;/a&gt;、&lt;a href=&#34;https://github.com/sgl-project/sglang&#34;&gt;sglang&lt;/a&gt;做模型推理服务部署是因为&lt;a href=&#34;https://github.com/ollama/ollama&#34;&gt;ollama&lt;/a&gt;能自动换入换出模型，一份计算资源，能分时复用跑多个模型。&lt;/p&gt;
&lt;h2 id=&#34;8-2-comfyui&#34;&gt;&lt;a href=&#34;#8-2-comfyui&#34; class=&#34;headerlink&#34; title=&#34;8.2 comfyui&#34;&gt;&lt;/a&gt;8.2 comfyui&lt;/h2&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 主要图像、视频类大模型工作流部署用，自由度很高，社区活跃，现成工作流配置和插件很多。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;官网：&lt;a href=&#34;https://docs.comfy.org/&#34;&gt;https://docs.comfy.org/&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;工作流来源：github（例如&lt;a href=&#34;https://github.com/comfyanonymous/ComfyUI_examples&#34;&gt;ComfyUI_examples&lt;/a&gt;）、&lt;a href=&#34;https://openart.ai/workflows/home&#34;&gt;openart&lt;/a&gt;、&lt;a href=&#34;https://comfyworkflows.com/&#34;&gt;comfyuiworkflows&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;8-3-openrouter&#34;&gt;&lt;a href=&#34;#8-3-openrouter&#34; class=&#34;headerlink&#34; title=&#34;8.3 openrouter&#34;&gt;&lt;/a&gt;8.3 openrouter&lt;/h2&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 应该是全球最流行的大模型token池吧，各大厂定期会放一些新模型的免费token出来，这时&lt;a href=&#34;https://openrouter.ai/&#34;&gt;openrouter&lt;/a&gt;上通常就能找到对应的免费模型。申请个apikey就能调用openrouter接口，很方便，我vibe coding的主力模型通常都是通过&lt;a href=&#34;https://openrouter.ai/&#34;&gt;openrouter&lt;/a&gt;调用，&lt;a href=&#34;https://bailian.console.aliyun.com/cn-beijing/?tab=model#/model-market/all&#34;&gt;阿里的百炼&lt;/a&gt;作为补充，&lt;a href=&#34;https://github.com/ollama/ollama&#34;&gt;ollama&lt;/a&gt;部署模型兜底。&lt;/p&gt;
&lt;h1 id=&#34;9-笔记&#34;&gt;&lt;a href=&#34;#9-笔记&#34; class=&#34;headerlink&#34; title=&#34;9 笔记&#34;&gt;&lt;/a&gt;9 笔记&lt;/h1&gt;&lt;p&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; 市面上个人笔记王者是&lt;a href=&#34;https://obsidian.md/&#34;&gt;obsidian&lt;/a&gt;，协作笔记王者是&lt;a href=&#34;https://www.notion.so/&#34;&gt;notion&lt;/a&gt;。开源方案中&lt;a href=&#34;https://affine.pro/zhHans&#34;&gt;AFFiNE&lt;/a&gt;对标&lt;a href=&#34;https://www.notion.so/&#34;&gt;notion&lt;/a&gt;，就算不是王者也是第一梯队了，个人感觉能同时解决个人笔记和小团队协作文档的需求。核心feature贴一下：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;rust实现后端&lt;/li&gt;
&lt;li&gt;存储可端可云&lt;/li&gt;
&lt;li&gt;各端客户端都有&lt;/li&gt;
&lt;li&gt;支持Markdown编辑、导出&lt;/li&gt;
&lt;li&gt;支持画布&lt;/li&gt;
&lt;li&gt;支持接AI做续写、总结、问答等等&lt;/li&gt;
&lt;li&gt;支持协作&lt;/li&gt;
&lt;/ul&gt;
